1	package snapshot
2	
3	import (
4		"crypto/rand"
5		"encoding/binary"
6		"errors"
7		"hash/crc32"
8		"os"
9		"path/filepath"
10		"syscall"
11		"time"
12	)
13	
14	// Chain directory coordination.
15	//
16	// A backup chain directory is shared state: several store objects — in this
17	// process or in others — may export into it, merge it or restore from it at
18	// the same time. To keep the chain consistent, every such operation first
19	// takes the chain's lease: a small sibling file ("<chain>.lease") that names
20	// its holder (a process id plus a random token) and carries an expiry time.
21	// At most one registered operation holds the lease at a time; an operation
22	// that cannot take it fails wholesale with an error wrapping fs.ErrInvalid
23	// and touches nothing on or around the chain.
24	//
25	// The lease is reclaimed, never waited on. A holder that is force-killed
26	// leaves the file behind, and the next backup, merge, restore or open of a
27	// related directory recognizes the lease as stale — its holder process is
28	// gone or its expiry has passed — removes it and proceeds. The chain is
29	// therefore never wedged behind a dead holder and needs no manual cleanup.
30	// A live holder renews its expiry in the background, so a long export or
31	// merge is never reclaimed from under itself.
32	//
33	// The lease file lives next to the chain directory, not inside it, so it is
34	// never part of the artifact the whole-chain validation sees, and a leftover
35	// lease can never make a complete chain unreadable.
36	const (
37		chainLeaseSuffix = ".lease"
38	
39		leaseMagic   uint32 = 0x4b4c4b53 // bytes "SKLK"
40		leaseVersion uint32 = 1
41	
42		// leaseSize is magic, version, holder pid, holder token and expiry; the
43		// terminal CRC follows it.
44		leaseSize = 4 + 4 + 8 + 8 + 8
45	
46		// leaseTTL is how long a lease stays fresh without a renewal. It only
47		// ever retires a lease whose holder stopped renewing — a killed holder
48		// (or one whose pid can no longer be confirmed) — never a live one,
49		// which renews well inside the TTL.
50		leaseTTL = 30 * time.Second
51		// leaseHeartbeat is how often a live holder re-stamps its lease.
52		leaseHeartbeat = 5 * time.Second
53	)
54	
55	// chainLease is a held chain lease. The zero value holds nothing.
56	type chainLease struct {
57		path  string
58		info  os.FileInfo // identity of the lease file this holder created
59		pid   uint64
60		token uint64
61		stop  chan struct{}
62		done  chan struct{}
63	}
64	
65	// acquireChainLease takes the lease coordinating operations on the chain
66	// directory chainDir. A lease left behind by a killed holder is reclaimed on
67	// the spot; a lease still held by a live operation fails the whole call with
68	// an error wrapping fs.ErrInvalid. The lease is never waited on.
69	func acquireChainLease(chainDir string) (*chainLease, error) {
70		parent := filepath.Dir(chainDir)
71		if info, err := os.Stat(parent); err != nil {
72			if errors.Is(err, os.ErrNotExist) {
73				return nil, errBadBackup
74			}
75			return nil, err
76		} else if !info.IsDir() {
77			return nil, errBadBackup
78		}
79		path := filepath.Join(parent, filepath.Base(chainDir)+chainLeaseSuffix)
80		for attempt := 0; attempt < 8; attempt++ {
81			l, err := tryAcquireLease(path)
82			if err == nil {
83				return l, nil
84			}
85			if !errors.Is(err, os.ErrExist) {
86				return nil, err
87			}
88			stale, err := leaseIsStale(path)
89			if err != nil {
90				return nil, err
91			}
92			if !stale {
93				// A live operation holds the chain.
94				return nil, errBadBackup
95			}
96			// Reclaim the dead holder's lease. A contender may win the removal
97			// or the next create; either way the loop re-reads the state and
98			// exactly one contender ends up holding the lease.
99			_ = os.Remove(path)
100		}
101		return nil, errBadBackup
102	}
103	
104	// tryAcquireLease creates the lease file exclusively and stamps it with this
105	// process's holder identity. It fails with os.ErrExist when a lease file
106	// already exists.
107	func tryAcquireLease(path string) (*chainLease, error) {
108		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
109		if err != nil {
110			return nil, err
111		}
112		var token [8]byte
113		if _, err := rand.Read(token[:]); err != nil {
114			f.Close()
115			os.Remove(path)
116			return nil, err
117		}
118		l := &chainLease{
119			path:  path,
120			pid:   uint64(os.Getpid()),
121			token: binary.LittleEndian.Uint64(token[:]),
122			stop:  make(chan struct{}),
123			done:  make(chan struct{}),
124		}
125		fail := func(err error) (*chainLease, error) {
126			f.Close()
127			os.Remove(path)
128			return nil, err
129		}
130		if _, err := f.Write(l.stamp()); err != nil {
131			return fail(err)
132		}
133		if err := f.Sync(); err != nil {
134			return fail(err)
135		}
136		info, err := f.Stat()
137		if err != nil {
138			return fail(err)
139		}
140		if err := f.Close(); err != nil {
141			os.Remove(path)
142			return nil, err
143		}
144		// Confirm the file on the path is still the one just created: a
145		// contender that reclaimed and recreated it in the meantime holds the
146		// lease, not us.
147		cur, err := os.Stat(path)
148		if err != nil {
149			os.Remove(path)
150			if errors.Is(err, os.ErrNotExist) {
151				return nil, errBadBackup
152			}
153			return nil, err
154		}
155		if !os.SameFile(cur, info) {
156			return nil, errBadBackup
157		}
158		l.info = info
159		go l.heartbeat()
160		return l, nil
161	}
162	
163	// stamp renders the lease content with a fresh expiry.
164	func (l *chainLease) stamp() []byte {
165		buf := make([]byte, leaseSize+crcSize)
166		binary.LittleEndian.PutUint32(buf[0:4], leaseMagic)
167		binary.LittleEndian.PutUint32(buf[4:8], leaseVersion)
168		binary.LittleEndian.PutUint64(buf[8:16], l.pid)
169		binary.LittleEndian.PutUint64(buf[16:24], l.token)
170		binary.LittleEndian.PutUint64(buf[24:32], uint64(time.Now().Add(leaseTTL).UnixNano()))
171		binary.LittleEndian.PutUint32(buf[32:36], crc32.ChecksumIEEE(buf[:leaseSize]))
172		return buf
173	}
174	
175	// heartbeat keeps the lease fresh until release; a live holder's lease
176	// therefore never expires no matter how long its operation runs.
177	func (l *chainLease) heartbeat() {
178		defer close(l.done)
179		ticker := time.NewTicker(leaseHeartbeat)
180		defer ticker.Stop()
181		for {
182			select {
183			case <-l.stop:
184				return
185			case <-ticker.C:
186				l.renew()
187			}
188		}
189	}
190	
191	// renew re-stamps the lease with a fresh expiry, best-effort: if the file is
192	// no longer the one this holder created there is nothing to renew.
193	func (l *chainLease) renew() {
194		cur, err := os.Stat(l.path)
195		if err != nil || !os.SameFile(cur, l.info) {
196			return
197		}
198		f, err := os.OpenFile(l.path, os.O_WRONLY|os.O_TRUNC, 0o600)
199		if err != nil {
200			return
201		}
202		if _, err := f.Write(l.stamp()); err == nil {
203			_ = f.Sync()
204		}
205		_ = f.Close()
206	}
207	
208	// release gives the lease back. Only the file this holder created is
209	// removed: a lease reclaimed and re-created by someone else is theirs.
210	func (l *chainLease) release() {
211		close(l.stop)
212		<-l.done
213		cur, err := os.Stat(l.path)
214		if err == nil && os.SameFile(cur, l.info) {
215			_ = os.Remove(l.path)
216		}
217	}
218	
219	// parseLease decodes lease file content; ok is false for anything that is
220	// not a well-formed, checksum-good lease of a known version.
221	func parseLease(data []byte) (pid, token uint64, expiry int64, ok bool) {
222		if len(data) != leaseSize+crcSize {
223			return 0, 0, 0, false
224		}
225		if binary.LittleEndian.Uint32(data[0:4]) != leaseMagic ||
226			binary.LittleEndian.Uint32(data[4:8]) != leaseVersion {
227			return 0, 0, 0, false
228		}
229		if binary.LittleEndian.Uint32(data[32:36]) != crc32.ChecksumIEEE(data[:leaseSize]) {
230			return 0, 0, 0, false
231		}
232		return binary.LittleEndian.Uint64(data[8:16]),
233			binary.LittleEndian.Uint64(data[16:24]),
234			int64(binary.LittleEndian.Uint64(data[24:32])), true
235	}
236	
237	// leaseIsStale reports whether the lease at path was abandoned: its holder
238	// process is certainly gone, or its expiry has passed (a live holder renews
239	// long before that). A missing file counts as stale so the caller's create
240	// retry proceeds.
241	func leaseIsStale(path string) (bool, error) {
242		data, err := os.ReadFile(path)
243		if err != nil {
244			if errors.Is(err, os.ErrNotExist) {
245				return true, nil
246			}
247			return false, err
248		}
249		pid, _, expiry, ok := parseLease(data)
250		if !ok {
251			// Not a readable lease: either foreign content or a lease caught
252			// mid-write. Reclaim it only once it is clearly old, so a live
253			// writer finishing its create is never clobbered.
254			info, serr := os.Stat(path)
255			if serr != nil {
256				if errors.Is(serr, os.ErrNotExist) {
257					return true, nil
258				}
259				return false, serr
260			}
261			return time.Since(info.ModTime()) > leaseTTL, nil
262		}
263		if alive, certain := processAlive(pid); certain && !alive {
264			return true, nil
265		}
266		return time.Now().UnixNano() > expiry, nil
267	}
268	
269	// processAlive reports whether pid names a live process. certain is false
270	// when the platform cannot answer (the caller then falls back to the lease
271	// expiry); a process that exists but belongs to another user counts as
272	// alive.
273	func processAlive(pid uint64) (alive, certain bool) {
274		if pid == 0 || int64(pid) < 0 || pid != uint64(int(pid)) {
275			return false, true
276		}
277		p, err := os.FindProcess(int(pid))
278		if err != nil {
279			return false, false
280		}
281		err = p.Signal(syscall.Signal(0))
282		switch {
283		case err == nil:
284			return true, true
285		case errors.Is(err, syscall.EPERM):
286			return true, true
287		case errors.Is(err, syscall.ESRCH), errors.Is(err, os.ErrProcessDone):
288			return false, true
289		default:
290			// Signal 0 is not implemented everywhere; when it is not, the
291			// lease expiry alone decides.
292			return false, false
293		}
294	}
295	
296	// reclaimStaleLease removes the lease coordinating operations on chainDir
297	// when its holder is gone. It is the open-time counterpart of the
298	// acquisition-time reclamation: a directory related to a killed operation
299	// opens normally, with no lease wedged behind a dead holder. Best-effort,
300	// like the other open-time sweeps.
301	func reclaimStaleLease(chainDir string) {
302		parent := filepath.Dir(chainDir)
303		path := filepath.Join(parent, filepath.Base(chainDir)+chainLeaseSuffix)
304		if _, err := os.Stat(path); err != nil {
305			return
306		}
307		stale, err := leaseIsStale(path)
308		if err != nil || !stale {
309			return
310		}
311		_ = os.Remove(path)
312	}
