623	// sweepMergeDebris clears the sibling directories a merge can leave next to
624	// chainDir when it is killed: a staging chain ("<base>.merge-new-*") and a
625	// retired old chain ("<base>.merge-old-*"). If the chain path itself is
626	// missing but a retired old chain exists, the merge was killed between the
627	// two commit renames and the whole old chain is moved back into place first.
628	// It is best-effort: leftover debris never affects the chain at chainDir.
629	func sweepMergeDebris(chainDir string) {
630		parent := filepath.Dir(chainDir)
631		base := filepath.Base(chainDir)
632		entries, err := os.ReadDir(parent)
633		if err != nil {
634			return
635		}
636		var staging, trash []string
637		for _, e := range entries {
638			if !e.IsDir() {
639				continue
640			}
641			name := e.Name()
642			if isMergeTempName(name, base, mergeStagePrefix) {
643				staging = append(staging, name)
644			}
645			if isMergeTempName(name, base, mergeTrashPrefix) {
646				trash = append(trash, name)
647			}
648		}
649		if len(staging) == 0 && len(trash) == 0 {
650			return
651		}
652		changed := false
653		if _, err := os.Stat(chainDir); errors.Is(err, os.ErrNotExist) && len(trash) > 0 {
654			// Killed between the two commit renames: the old chain is whole in
655			// the trash sibling; put it back before clearing anything.
656			if err := os.Rename(filepath.Join(parent, trash[0]), chainDir); err == nil {
657				changed = true
658				trash = trash[1:]
659			}
660		}
661		for _, name := range staging {
662			if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
663				changed = true
664			}
665		}
666		for _, name := range trash {
667			if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
668				changed = true
669			}
670		}
671		if changed {
672			_ = syncDirectory(parent)
673		}
674	}
675	
676	// isMergeTempName reports whether name is a merge staging or trash directory
677	// for the chain named base.
678	func isMergeTempName(name, base, prefix string) bool {
679		p := base + prefix
680		return len(name) > len(p) && name[:len(p)] == p
681	}
682

