	if err != nil {
		_ = os.RemoveAll(stage)
		return err
	}
	abort := func(cause error) error {
		_ = os.RemoveAll(stage)
		_ = os.RemoveAll(diag)
		return cause
	}

	// Hard-link the intact prefix into staging: its bytes are the exact files
	// already validated, copied without being read.
