// copyChainInto duplicates src's files into dst, which must not exist yet.
func copyChainInto(t *testing.T, src, dst string) {
	t.Helper()
	if err := os.MkdirAll(dst, 0o700); err != nil {
		t.Fatal(err)
	}
	entries, err := os.ReadDir(src)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if e.IsDir() {
			t.Fatalf("source contains directory %q", e.Name())
		}
		data, err := os.ReadFile(filepath.Join(src, e.Name()))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(dst, e.Name()), data, 0o600); err != nil {
			t.Fatal(err)
		}
	}
}

// verifyDiagDir finds the diagnostic sibling directory verification leaves
// next to chainDir, failing if it is absent.
func verifyDiagDir(t *testing.T, chainDir string) string {
	t.Helper()
	parent := filepath.Dir(chainDir)
	base := filepath.Base(chainDir)
	entries, err := os.ReadDir(parent)
	if err != nil {
		t.Fatal(err)
	}
	prefix := base + verifyDiagPrefix
	for _, e := range entries {
		if e.IsDir() && len(e.Name()) > len(prefix) && e.Name()[:len(prefix)] == prefix {
			return filepath.Join(parent, e.Name())
		}
	}
	t.Fatal("no diagnostic directory next to chain")
	return ""
}

