108		if !info.IsDir() {
109			return errBadBackup
110		}
111		// Residual staging from an export killed mid-run is debris, never a
112		// foreign entry: clear it before classifying the chain.
113		if err := sweepBackupDebris(chainDir); err != nil {
114			return err
115		}
116	
117		goodRings, ok, err := classifyIntactPrefix(chainDir)
118		if err != nil {
119			return err
120		}
121		if !ok {
122			// The head itself is unusable: there is no intact prefix to fall back
123			// to. Reject wholesale and change nothing.
124			return errBadBackup
125		}
126		total, err := countRingFiles(chainDir)
127		if err != nil {
128			return err
129		}
130		if goodRings == total {
131			// Intact chain: the directory bytes are left exactly as found.
132			return nil
133		}
134		return commitDegradedChain(chainDir, goodRings)
135	}
136	
137	// classifyIntactPrefix streams the whole chain and returns the number of its
138	// leading rings that are intact. ok is false when the chain cannot be trusted
139	// even as a head-only chain (a foreign entry, an unusable head or damaged head
140	// segments), which the caller must reject without degrading.
141	//
142	// It streams every file with bounded buffers and retains no entry content. A
143	// genuine I/O failure passes through unchanged; every structural or content
144	// defect maps to ok == false (head) or a shorter intact prefix (rings).
145	func classifyIntactPrefix(chainDir string) (goodRings uint32, ok bool, err error) {
146		entries, err := os.ReadDir(chainDir)
147		if err != nil {
148			return 0, false, err
149		}
150	
151		// File layout first: any foreign entry rejects the whole directory,
152		// independent of where a content defect might sit.
153		manifestPresent := false
154		segFiles := make(map[uint32]bool)
155		ringFiles := make(map[uint32]bool)
156		for _, e := range entries {
157			name := e.Name()
158			if e.IsDir() {
159				return 0, false, nil // no staging or foreign directory in a chain
160			}
161			switch {
162			case name == backupManifest:
163				manifestPresent = true
164			case name == backupManifestTmp:
165				return 0, false, nil // an unfinished manifest is foreign debris here
166			default:
167				if idx, isSeg := parseSegmentIndex(name); isSeg {
168					segFiles[idx] = true
169					continue
170				}
171				if idx, isRing := parseRingIndex(name); isRing {
172					ringFiles[idx] = true
173					continue
174				}
175				return 0, false, nil // foreign file
176			}
177		}
178		if !manifestPresent {
179			return 0, false, nil // no usable chain head
180		}
181	
